import { marked } from 'marked';
import { parse } from 'yaml';

export type Book = {
	slug: string;
	title: string;
	author: string;
	year: number;
	rating: number;
	tags: string[];
};

const files = import.meta.glob('/content/books/*.md', {
	query: '?raw',
	import: 'default',
	eager: true
}) as Record<string, string>;

const all = Object.entries(files).map(([path, raw]) => {
	const slug = path.split('/').pop()!.replace(/\.md$/, '');
	const m = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
	const data = parse(m ? m[1] : '') ?? {};
	const book: Book = {
		slug,
		title: String(data.title),
		author: String(data.author),
		year: Number(data.year),
		rating: Number(data.rating),
		tags: (data.tags ?? []).map(String)
	};
	return { book, body: m ? m[2] : raw };
});

const byTitle = (a: Book, b: Book) => (a.title < b.title ? -1 : a.title > b.title ? 1 : 0);

export function getBooks(): Book[] {
	return all.map((x) => x.book).sort(byTitle);
}

export function getTopRated(n = 3): Book[] {
	return getBooks()
		.sort((a, b) => b.rating - a.rating || byTitle(a, b))
		.slice(0, n);
}

export function getBook(slug: string) {
	const found = all.find((x) => x.book.slug === slug);
	if (!found) return undefined;
	return { ...found.book, html: marked.parse(found.body, { async: false }) as string };
}
EOF
