// Starts the production build. The site is reached over plain http, so tell the
// node adapter which protocol to use (from ORIGIN) when it builds the request URL.
import http from 'node:http';

const protocol = new URL(process.env.ORIGIN ?? 'http://localhost').protocol.replace(':', '');
process.env.PROTOCOL_HEADER = 'x-forwarded-proto';

const createServer = http.createServer;
http.createServer = (...args) => {
	const server = createServer(...args);
	server.on('request', (req) => {
		req.headers['x-forwarded-proto'] = protocol;
	});
	return server;
};

await import('./build/index.js');
EOF
